// Call tbapi_version and defensively validate per API notes
const char *ver = tbapi_version();
// Nullability is unspecified; bail if NULL to avoid dereference
if (!ver) { FUZZ_BAIL(); }

// Safely determine length without assuming proper termination beyond a bound
// Keep scan bounded for fuzzer performance and safety
size_t max_scan = 2048; // within guidance (<2048 bytes)
size_t len = 0;
while (len < max_scan && ver[len] != '\0') { ++len; }
// If not terminated within bound, bail to avoid over-read of static buffer
if (len == max_scan) { FUZZ_BAIL(); }

// Copy into a local std::string to exercise read access without modifying or freeing the source
std::string ver_copy(ver, len);

// Optionally touch a few bytes to exercise read paths; never modify original
if (len > 0) {
    volatile unsigned char first = static_cast<unsigned char>(ver[0]);
    (void)first;
}
// Do not free or store ver; ownership and lifetime unspecified. No outputs returned.
